{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "IRG incident record",
  "description": "One coded AI safety incident. Taxonomy v0.1. Every factual claim must trace to a public source.",
  "type": "object",
  "required": [
    "id",
    "title",
    "date_of_event",
    "sources",
    "source_strength",
    "primary_class",
    "detection_locus",
    "discovery_lag",
    "disclosure_lag",
    "disclosure_incentive",
    "severity",
    "clock_start",
    "counterfactual_catch",
    "counterfactual_justification",
    "coder",
    "coded_on",
    "record_status"
  ],
  "additionalProperties": false,
  "properties": {
    "id": {
      "type": "string",
      "pattern": "^IRG-[0-9]{4}$",
      "description": "Stable identifier, e.g. IRG-0001."
    },
    "title": { "type": "string", "minLength": 8, "maxLength": 160 },
    "summary": {
      "type": "string",
      "maxLength": 1200,
      "description": "Neutral description of what was documented. No inferred intent."
    },
    "developer": {
      "type": "string",
      "description": "Organisation that built the system, if publicly established. Use 'unattributed' if not."
    },
    "date_of_event": {
      "type": "string",
      "description": "ISO date or YYYY-MM or YYYY. Use 'unknown' if sources do not establish it."
    },
    "date_public": { "type": "string" },
    "sources": {
      "type": "array",
      "minItems": 1,
      "description": "Public URLs. A record with no source is not a record.",
      "items": {
        "type": "object",
        "required": ["url", "kind"],
        "additionalProperties": false,
        "properties": {
          "url": { "type": "string", "pattern": "^https?://" },
          "kind": {
            "type": "string",
            "enum": [
              "regulatory-filing",
              "developer-publication",
              "incident-database",
              "court-document",
              "peer-reviewed",
              "press",
              "other"
            ]
          },
          "note": { "type": "string" }
        }
      }
    },
    "source_strength": {
      "type": "string",
      "enum": ["primary-documented", "corroborated-secondary", "single-secondary", "contested"],
      "description": "How well the event itself is established, independent of our coding."
    },
    "primary_class": {
      "type": "string",
      "enum": ["A1", "A2", "A3", "A4", "A5", "A6", "A7", "A8", "A9", "A10"]
    },
    "secondary_classes": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": ["A1", "A2", "A3", "A4", "A5", "A6", "A7", "A8", "A9", "A10"]
      },
      "uniqueItems": true
    },
    "detection_locus": {
      "type": "string",
      "enum": ["developer-internal-only", "deployer", "user", "public", "researcher-probe"]
    },
    "discovery_lag": {
      "type": "string",
      "enum": ["<24h", "1-7d", "1-4wk", "1-6mo", ">6mo", "unknown"]
    },
    "disclosure_lag": {
      "type": "string",
      "enum": ["<24h", "1-7d", "1-4wk", "1-6mo", ">6mo", "never-voluntarily", "unknown"]
    },
    "disclosure_incentive": {
      "type": "string",
      "enum": ["aligned", "neutral", "adverse", "strongly-adverse"]
    },
    "severity": {
      "type": "object",
      "required": ["reversibility", "breadth", "control_relevance", "precedent"],
      "additionalProperties": false,
      "description": "Four ordinal axes, 0-3. Deliberately not summed.",
      "properties": {
        "reversibility": { "type": "integer", "minimum": 0, "maximum": 3 },
        "breadth": { "type": "integer", "minimum": 0, "maximum": 3 },
        "control_relevance": { "type": "integer", "minimum": 0, "maximum": 3 },
        "precedent": { "type": "integer", "minimum": 0, "maximum": 3 }
      }
    },
    "clock_start": {
      "type": "string",
      "enum": ["unambiguous", "graded", "contested"]
    },
    "counterfactual_catch": {
      "type": "string",
      "enum": ["yes", "late", "partial-or-minimised", "no", "unknown"]
    },
    "counterfactual_justification": {
      "type": "string",
      "minLength": 120,
      "description": "One paragraph citing B1-B6. Required: this field is the analysis."
    },
    "coder": { "type": "string" },
    "second_coder": { "type": "string" },
    "coded_on": { "type": "string" },
    "disagreements": {
      "type": "array",
      "description": "Fields where the two coders differed, recorded rather than reconciled silently.",
      "items": {
        "type": "object",
        "required": ["field", "coder_value", "second_coder_value"],
        "additionalProperties": false,
        "properties": {
          "field": { "type": "string" },
          "coder_value": { "type": "string" },
          "second_coder_value": { "type": "string" },
          "resolution": { "type": "string" }
        }
      }
    },
    "record_status": {
      "type": "string",
      "enum": ["synthetic-example", "single-coded", "double-coded", "published", "withdrawn"],
      "description": "Only double-coded or published records may be used in any reported statistic."
    },
    "notes": { "type": "string" }
  }
}

